    ["01-9"] = {tips={{k="交通", text="Humanos: tomad el Tranvía Subterráneo de Ventormenta a Forjaz. Elfos de la noche: tomad el barco a Ventormenta y luego el tranvía. Los Skyborne se saltan esta parada: en la parada 8 cruzan el portal de Dalaran a Ventormenta y luego van en barco a Costa Oscura.", s={{"Humanos: tomad el Tranvía Subterráneo de Ventormenta a Forjaz", {race={"Human"}}}, {"Elfos de la noche: tomad el barco a Ventormenta y luego el tranvía", {race={"NightElf"}}}, {"Los Skyborne se saltan esta parada: en la parada 8 cruzan el portal de Dalaran a Ventormenta y luego van en barco a Costa Oscura", {race={"天裔"}}}}}}, steps={[1]={npc="Rudra Calmámbar", tgt="Rudra Calmámbar", tag="Opcional, Grupo recomendado"}, [2]={hint="Rudra Cieloámbar quiere que mates a Vagash y que le lleves su colmillo al rancho de carneros.", tag="Opcional, Grupo recomendado"}, [3]={npc="Rudra Calmámbar", tgt="Rudra Calmámbar", tag="Opcional, Grupo recomendado"}, [4]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [5]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [6]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [7]={npc="Senador Mehr Piedrasanta", tgt="Senador Mehr Piedrasanta"}, [8]={npc="Supervisor Petrocejas", tgt="Supervisor Petrocejas"}, [9]={hint="Mata a 10 espías Hierro Negro en Dun Morogh."}, [10]={npc="Mapa Hierro Negro", npcObj=true, desc="Haz clic derecho en Mapa Hierro Negro en tu bolsa para empezar la misión."}, [11]={hint="Mata a 10 quebrantahuesos Comepiedras para el senador Mehr Piedrasanta de la Cantera de Gol'Bolar."}, [12]={npc="Supervisor Petrocejas", tgt="Supervisor Petrocejas"}, [13]={npc="Senador Mehr Piedrasanta", tgt="Senador Mehr Piedrasanta"}, [14]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [15]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [16]={npc="Piloto Podomartillo", tgt="Piloto Podomartillo"}, [17]={npc="Un cadáver de enano", npcObj=true}, [18]={npc="Un cadáver de enano", npcObj=true}, [19]={hint="Mata a Zarpasarnosa."}, 