    ["02-10"] = {steps={[1]={npc="Maniveo Zumbang", tgt="Maniveo Zumbang"}, [2]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [3]={node="Auberdine"}, [4]={hint="Reúne 6 piernas de reptador y colócalas en la caja mecánica 827."}, [5]={hint="Recoge huesos de la criatura marina varada que está al sur de Auberdine y llévaselos a Gwennyth Bly'Leggonde a Auberdine."}, [6]={npc="Caja mecánica 827", npcObj=true}, [7]={npc="Caja mecánica 827", npcObj=true}, [8]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [9]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [10]={hint="Lleva 8 piezas de mineral de elunita y el Medallón de Elura a Elanaria en Darnassus."}, [11]={npc="Cerellean Zarpablanca", tgt="Cerellean Zarpablanca"}, [12]={hint="Recoge restos de la tortuga marina esquelética de las aguas del oeste de Auberdine y vuelve a Auberdine a hablar con Gwennyth Bly'Leggonde."}, [13]={hint="Consigue 3 ojos de trillador de los trilladores de Costa Oscura en las profundidades del mar, cerca de la caja mecánica 411."}, [14]={text="Sigue el camino hasta este punto."}, [15]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [16]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [17]={npc="Tharnariun Espinarbolado", tgt="Tharnariun Espinarbolado"}, [18]={npc="Terenthis", tgt="Terenthis"}, [19]={text="Sigue el camino hasta este punto."}, [20]={hint="Captura un Oso Cardo rabioso vivo y llévaselo a Tharnariun."}, [21]={hint="Utiliza el polvo de luna Cenarion en la piedra de lechúcico lunar de Auberdine para invocar a Garraluna. Luego tendrás que enfrentarte a Garraluna y ganar la fuerza física y de corazón que posee."}, [22]={npc="Asterion", tgt="Asterion"}, [23]={npc="Asterion", tgt="Asterion"}, [24]={hint="Consigue 8 pendientes de grell y llévaselos a Asterion a Bashal'Aran."}, [25]={npc="Asterion", tgt="Asterion"}, [26]={npc="Asterion", tgt="Asterion"}, [27]={hint="Consigue el lacre de piedra lunar antiguo y llévaselo a Asterion a Bas