n."}, [72]={hint="Recupera la insignia de Haggar del campamento de Jack Dentomuerto y regresa con el alguacil Haggard.", desc="Jack Dentomuerto está en el campamento al norte del Aserradero de la Vega del Este, en el Bosque de Elwynn."}, [73]={npc="Alguacil Haggard", tgt="Alguacil Haggard", desc="Jack Dentomuerto está en el campamento al norte del Aserradero de la Vega del Este, en el Bosque de Elwynn."}, [74]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra"}, [75]={npc="Remen Marcot", tgt="Remen Marcot", tag="Opcional", desc="Misión de introducción de los humanos en Villadorada. Puedes ir directamente a Gakin el Presotenebra y aceptar la Surena Caledon."}, [76]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra", tag="Opcional", desc="Misión de introducción de los humanos en Villadorada. Puedes ir directamente a Gakin el Presotenebra y aceptar la Surena Caledon."}, [77]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra", desc="Surena Caledon está en la granja del huerto de calabazas de los Brackwell, en el Bosque de Elwynn."}, [78]={hint="Consigue la gargantilla de Surena para Gakin el Presotenebra de Ventormenta.", desc="Surena Caledon está en la granja del huerto de calabazas de los Brackwell, en el Bosque de Elwynn."}, [79]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra", desc="Surena Caledon está en la granja del huerto de calabazas de los Brackwell, en el Bosque de Elwynn."}, [80]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra", desc="Usa el objeto en el círculo de invocación junto a Gakin el Presotenebra y derrota al Abisario invocado."}, [81]={hint="Con la gargantilla de sangrita, invoca y somete a un abisario. Después devuelve la gargantilla de sangrita a Gakin el Presotenebra, en Ventormenta.", desc="Usa el objeto en el círculo de invocación junto a Gakin el Presotenebra y derrota al Abisario invocado."}, [82]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra", desc="Usa el objeto en el círculo de invocación