    ["02-11"] = {steps={[1]={node="Ventormenta"}, [2]={text="Sal de Ventormenta y sigue el camino del Bosque de Elwynn hacia el oeste, pasa por Villadorada y cruza el puente hacia los Páramos de Poniente; luego sigue la carretera principal al sur hasta la Colina del Centinela.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [3]={npc="Ayudante del alguacil Rainer", tgt="Ayudante del alguacil Rainer"}, [4]={npc="Granjero Cejade", tgt="Granjero Cejade"}, [5]={npc="Verna Cejade", tgt="Verna Cejade"}, [6]={npc="Verna Cejade", tgt="Verna Cejade"}, [7]={hint="Verna Furlbrow de los Páramos de Poniente quiere que le lleves 8 puñados de avena.", tag="Opcional"}, [8]={npc="Granjero Saldean", tgt="Granjero Saldean"}, [9]={npc="Salma Saldean", tgt="Salma Saldean"}, [10]={npc="Ozwin Ferropiñón", tgt="Ozwin Ferropiñón"}, [11]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [12]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [13]={node="Colina del Centinela"}, [14]={npc="Explorador Galiaan", tgt="Explorador Galiaan"}, [15]={npc="Alba Lunajusta", tgt="Alba Lunajusta"}, [16]={npc="Alba Lunajusta", tgt="Alba Lunajusta"}, [17]={hint="Usa el equipo de muestras de agua de pozo para conseguir muestras de los pozos de la Finca de Jansen y la Granja de Molsen."}, [18]={hint="El granjero Furlbrow quiere que recuperes el reloj de bolsillo que dejó olvidado en el armario de su granja en la plantación de calabazas del Oeste.", desc="Ajustando la cámara puedes recogerlo desde fuera."}, [19]={hint="Alba Lunajusta quiere que consigas 7 branquias de múrloc de Playa Larga por la cosa de los Páramos de Poniente."}, [20]={npc="Granjero Cejade", tgt="Granjero Cejade"}, [21]={hint="El granjero Saldean quiere que mates 20 Vigilantes de la cosecha."}, [22]={npc="Verna Cejade", tgt="Verna Cejade"}, [23]={npc="Granjero Saldean", tgt="Granjero Saldean"}, [24]={npc="Alba Lunajusta", tgt="Alba Lunajusta"}, [25]={npc="Alba Lunajusta", tgt="Alba Lunajusta"}, [26]={npc="Alba Lunajust