    ["05-d1"] = {name="El Salón de los Feudales", entrance="Forjaz 27.63, 47.83", steps={[1]={npc="Mapa Hierro Negro", npcObj=true, tag="Requisito de mazmorra"}, [2]={npc="Videnterra Farsen", tgt="Videnterra Farsen", tag="Requisito de mazmorra"}, [3]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [4]={npc="Afadra Murocre", tgt="Afadra Murocre"}, [5]={npc="Thom Filch", tgt="Thom Filch"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="Entrada: El Salón de los Feudales"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="Mata a 15 apariciones iracundas y 10 almas atormentadas, antes de acabar con el espíritu de Yunquemar."}, [10]={hint="Recupera 8 reliquias enanas en el Salón de los Feudales."}, [11]={hint="Entra en el Salón de los Feudales bajo Antigua Forjaz y hazte con la cabeza de Durgen Martillo Funesto."}, [12]={npc="Treaty of Understanding", npcObj=true, desc="Haz clic derecho en Tratado de entendimiento en tu bolsa para empezar la misión. El jefe final lanza Miedo hacia el 35 % de salud. Limpia primero los esbirros y luego lleva al jefe a la sala anterior. Junto a quien da la misión hay una palanca. Tira de ella para abrir la puerta y sal en línea recta."}, [13]={npc="Thom Filch", tgt="Thom Filch"}, [14]={npc="Afadra Murocre", tgt="Afadra Murocre"}, [15]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}, [16]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}}},
    ["02-12"] = {steps={[1]={npc="Gryth Thurden", tgt="Gryth Thurden"}, [2]={node="Forjaz"}, [4]={text="Sal de Forjaz y sigue el camino hacia el este, atraviesa el túnel del paso oriental hasta Loch Modan y luego sigue el camino al noreste hasta Thelsamar.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [5]={node="Thelsamar"}, [6]={hint="El montaraz Gravagau, de la torre de vigilancia sur, quiere que mates a 10 aplastacráneos y 10 profetas Rompecantos. Luego ve a informarle."}, [7]={npc="Montaraz Gravagau", tgt="Montaraz Gravagau"}, [8]={npc="Montaraz Muroplof", tgt="Montaraz Muroplof"}, [9]={hint="Coge el Símbolo de la Vida y resucita a Narm Faulk en Dun Morogh."}, [10]={npc="Jern Cornamenta", tgt="Jern Cornamenta"}, [11]={npc="Brock Buscapiedras", tgt="Brock Buscapiedras"}, [12]={npc="Magmar Ceñimal", tgt="Magmar Ceñimal"}, [13]={npc="Magmar Ceñimal", tgt="Magmar Ceñimal"}, [14]={npc="Prospector Vetaferro", tgt="Prospector Vetaferro"}, [15]={npc="Daryl el Jovenzuelo", tgt="Daryl el Jovenzuelo"}, [16]={hint="Mata 6 águilas ratoneras montesas y ve a ver a Daryl el Jovenzuelo a la Cabaña del Errante en menos de 15 minutos."}, [17]={npc="Daryl el Jovenzuelo", tgt="Daryl el Jovenzuelo"}, [18]={npc="Daryl el Jovenzuelo", tgt="Daryl el Jovenzuelo"}, [19]={hint="Mata 5 jabalís monteses mayores y ve a ver a Daryl el Jovenzuelo a la Cabaña del Errante en menos de 12 minutos."}, [20]={npc="Daryl el Jovenzuelo", tgt="Daryl el Jovenzuelo"}, [21]={npc="Marek Coracero", tgt="Marek Coracero"}, [22]={npc="Marek Coracero", tgt="Marek Coracero"}, [23]={npc="Bingles Pimpampum", tgt="Bingles Pimpampum"}, [24]={npc="Bingles Pimpampum", tgt="Bingles Pimpampum"}, [25]={hint="Encuentra y derrota al crocolisco Dagacolmillo y recupera el cuchillo de Marek."}, [26]={hint="Lleva 5 piezas de carne de crocolisco y 6 pieles de crocolisco a Marek Coracero, que está en la Cabaña del Errante."}, [27]={hint="Localiza las herramientas de Bingles y devuélveselas:"}, [28]={hint="El