]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [58]={hint="Recoge agua de Salto de Fonroca a la entrada de la cueva."}, [59]={npc="Alanndarian Arrullanoche", tgt="Alanndarian Arrullanoche"}, [60]={npc="Alanndarian Arrullanoche", tgt="Alanndarian Arrullanoche", desc="Recoge Raíz de tierra y Seta lunar en Costa Oscura y entrégalas en Auberdine."}, [61]={hint="Lleva 5 raíces de tierra y 12 hongos lunares a Alanndarian Arrullanoche a Auberdine, para que pueda preparar un bálsamo curativo.", desc="Recoge Raíz de tierra y Seta lunar en Costa Oscura y entrégalas en Auberdine."}, [62]={npc="Alanndarian Arrullanoche", tgt="Alanndarian Arrullanoche", desc="Recoge Raíz de tierra y Seta lunar en Costa Oscura y entrégalas en Auberdine."}, [63]={npc="Alanndarian Arrullanoche", tgt="Alanndarian Arrullanoche", desc="Usa el remedio con los ciervos enfermos de Costa Oscura."}, [64]={hint="Utiliza el bálsamo curativo para animales en los 10 ciervos enfermos que hay en Costa Oscura; el bálsamo debería curarlos. Se han avistado ciervos enfermos desde el sur del Río Fonroca hasta el norte de Auberdine y por toda la zona que lleva hasta el sur de Costa Oscura, donde empieza Vallefresno.", desc="Usa el remedio con los ciervos enfermos de Costa Oscura."}, [65]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [66]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar", desc="Entrega la misión para aprender Curar veneno."}, [67]={npc="Mathrengyl Garroso", tgt="Mathrengyl Garroso"}, [68]={npc="Mathrengyl Garroso", tgt="Mathrengyl Garroso"}, [69]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [70]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar", desc="Encuentra el Adorno de altar en el fondo del Lago Elune'ara."}, [71]={hint="Lleva un adorno de altar del Lago Elune'ara al Santuario de Remulos, al noroeste de Claro de la Luna. Usa el adorno en el santuario.", desc="Encuentra el Adorno de altar en el fondo del Lago Elune'ara."}, [72]={npc="Tajarri", tgt="Tajarri", desc="Encuentra el Adorno de altar en el fondo del Lago Elune'ara."}, [73]={npc="Tajarri", tgt="Tajarri"}, [74]={hint="Busca el colgante de Agilidad acuática y el colgante de Resistencia acuática. Habla con la gente de Claro de la Luna para conseguir pistas sobre la ubicación de los colgantes."}, [75]={}, [76]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [77]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar", desc="Entrega la misión para aprender Forma acuática."}, [78]={npc="Mathrengyl Garroso", tgt="Mathrengyl Garroso"}}},
    ["02-13"] = {steps={[1]={npc="Gubber Blump", tgt="Gubber Blump"}, [2]={npc="¡Se busca: Viscoso!", npcObj=true}, [3]={npc="Arqueólogo Hollee", tgt="Arqueólogo Hollee"}, [4]={npc="Arqueólogo Hollee", tgt="Arqueólogo Hollee"}, [5]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [6]={npc="Gorbold Mano de Acero", tgt="Gorbold Mano de Acero"}, [7]={npc="Gorbold Mano de Acero", tgt="Gorbold Mano de Acero"}, [8]={npc="Gershala Noctusurro", tgt="Gershala Noctusurro"}, [9]={npc="Terenthis", tgt="Terenthis"}, [10]={npc="Terenthis", tgt="Terenthis"}, [11]={npc="Cristal rojo misterioso", npcObj=true}, [12]={npc="Cristal rojo misterioso", npcObj=true}, [13]={npc="Asterion", tgt="Asterion"}, [14]={npc="Criatura marina varada", npcObj=true}, [15]={hint="Recupera la caja fuerte del Amanecer de plata y la caja fuerte del Halo de bruma para Gorbold Mano de Acero de Auberdine. Ambos objetos deberían estar en los cascos de los navíos naufragados al norte de la aldea."}, [16]={npc="Caja mecánica 411", npcObj=true}, [17]={npc="Caja mecánica 411", npcObj=true}, [18]={npc="Tortuga marina varada", npcObj=true}, [19]={text="Sigue el camino hasta este punto.", desc="A partir de aquí, mata a los Jabatos Acechalunas y Osos Cardo rabiosos que veas."}, [20]={text="Sigue el camino hasta este punto."}, [21]={hint="Viaja al norte de Auberdine hasta la primera cascada del Río Fonroca y recoge una muestra de agua."}, [22]={hint="Reúne 6 trozos de cangrejo de gran calidad para Gubber Blump de Auberdine."}, [23]={npc="Tortuga marina varada", npcObj=true}, [24]={npc="Balthule Golpesombra", tgt="Balthule Golpesombra"}, [25]={npc="Balthule Golpesombra", tgt="Balthule Golpesombra"}, [26]={hint="Reúne 4 pliegos gastados para Balthule Golpesombra acerca de La torre de Althalaxx."}, [27]={npc="Balthule Golpesombra", tgt="Balthule Golpesombra"}, [28]={npc="Balthule Golpesombra", tgt="Balthule Golpesombra"}, [29]={hint="Libra al bosque de 20 Osos Cardo rabiosos y ve a buscar a Tharnariun Espinarbola