    ["03-37"] = {steps={[2]={npc="Maestro de vigilantes Sorigal", tgt="Maestro de vigilantes Sorigal"}, [3]={text="Desde Villa Oscura, ve al este por el Paso de la Muerte hasta el Pantano de las Penas."}, [4]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [5]={hint="Llévale 10 pizcas de polvo de sueño a Krazek a Bahía del Botín. El polvo de sueño se obtiene de las crías de dragón que habitan en el Pantano de las Penas."}, [6]={hint="Mata a 8 crocoliscos Denteserra jóvenes, 10 girapenas y 10 jaguares del pantano, y después ve a ver al vigilante Biggs al Pantano de las Penas."}, [7]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [8]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [9]={npc="Cayada de Noboru", npcObj=true, tag="Opcional", desc="Haz clic derecho en Cayada de Noboru en tu bolsa para empezar la misión. Mata a Noboru el Garrote para conseguir una cayada gris y haz clic derecho en ella para empezar la misión."}, [10]={npc="Magtoor", tgt="Magtoor"}, [11]={npc="Magtoor", tgt="Magtoor"}, [12]={hint="Llévale 6 cristales draenetistas a Magtoor que está en El Malecón del Pantano de las Penas."}, [13]={hint="Mantén tu reputación con los Gelkis y lleva 1 fragmento de draenetista a Uthek la Sabia al Poblado Gelkis de Desolace."}, [14]={hint="Encuentra el cofre de la caravana en Retiro Fangoso, consigue los componentes de zahorí y llévaselos al vigilante Biggs."}, [15]={npc="Galen Bonguarda", tgt="Galen Bonguarda"}, [16]={npc="Caja fuerte de Galen", npcObj=true}, [17]={npc="Magtoor", tgt="Magtoor"}, [18]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [19]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [20]={text="Sigue el camino hasta este punto."}, [21]={hint="Llévale 8 piezas de madera a la deriva desecada al vigilante Biggs en el Pantano de las Penas."}, [22]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [23]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [24]={text="Desde el sur del Pantano de las Penas, entra en Las Tierras Devastadas y sigue el camino al 