    ["04-45"] = {steps={[1]={npc="Sigrun Extracero", tgt="Sigrun Extracero", tag="Opcional"}, [2]={npc="Garek", tgt="Garek", tag="Opcional"}, [3]={hint="Usa el Signo de la Tierra para activar el Pilar de Amatista, el de Ópalo y el de Diamante y así obtener las piedras rúnicas.", tag="Hazlo cuando te pille de paso", desc="Por el camino sueles conseguir Hechizos Llamarada ígnea. Si no cae ninguno, abandónala."}, [4]={npc="Sello de la Tierra", npcObj=true, tag="Opcional"}, [5]={npc="Garek", tgt="Garek", tag="Opcional"}, [6]={npc="Sigrun Extracero", tgt="Sigrun Extracero", tag="Opcional"}, [7]={hint="Mata al embajador Infernus en la Fortaleza de Angor llévale la prueba de su muerte al consejero Belgrum en Forjaz."}, [8]={text="Desde Tierras Inhóspitas, ve al oeste y entra en La Garganta de Fuego por el sendero de montaña junto al campamento de la Horda de Kargath. Rodea Kargath.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [9]={npc="Banco de madera", npcObj=true}, [10]={hint="Mata a 8 geólogos Hierro Negro y lleva 15 piezas de seda a la persona encerrada en los baños de La Garganta de Fuego."}, [11]={text="Mata a Margol la Furiosa: da mucha experiencia.", tag="Opcional"}, [12]={npc="Cuerno de Margol", npcObj=true, tag="Opcional", desc="Haz clic derecho en Cuerno de Margol en tu bolsa para empezar la misión."}, [13]={npc="Banco de madera", npcObj=true}, [14]={npc="Banco de madera", npcObj=true}, [15]={hint="Coge el libro de contabilidad de Buenacero y busca los objetos de la lista antes de ir a verlo a Tanaris."}, [16]={npc="Dorius Tienrroca", tgt="Dorius Tienrroca"}, [17]={npc="Carta chamuscada", npcObj=true}, [18]={npc="Carta chamuscada", npcObj=true}, [19]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [20]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [21]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [22]={nodeA="{a:1446}"}, [23]={npc="Se busca/Desaparecido/Objetos perdidos", np