{hint="Hansel Manospesadas quiere que mates 20 incendosaurios."}, [52]={hint="El traidor Hierro Negro llamado vigía Maltorius está en La Fosa de la Escoria de La Caldera, en La Garganta de Fuego.", tag="Hazlo cuando te pille de paso"}, [53]={hint="Busca la receta de fluido ardiente robada por el vigía Maltorius en la La Fosa de la Escoria de La Caldera. Llévasela al maestro herrero Cremación a La Garganta de Fuego."}, [54]={hint="Lleva 8 dagas chapadas en torio a Kalaran Espada del Viento."}, [55]={npc="Arqueólogo moribundo", tgt="Arqueólogo moribundo"}, [56]={npc="Arqueólogo moribundo", tgt="Arqueólogo moribundo", tag="Opcional"}, [57]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [58]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [59]={hint="Encuentra el artefacto misterioso que protegen los idólatras de Azote del Ocaso en el cuadrante noroeste de La Garganta de Fuego.", tag="Hazlo cuando te pille de paso"}, [60]={hint="Lleva un Símbolo de Ragnaros a Kalaran Espada del Viento.", tag="Hazlo cuando te pille de paso"}, [61]={npc="Zamael Cardolún", tgt="Zamael Cardolún", tag="Opcional"}, [62]={npc="Zamael Cardolún", tgt="Zamael Cardolún", tag="Opcional"}, [63]={npc="Zamael Cardolún", tgt="Zamael Cardolún", tag="Opcional"}, [64]={npc="Capitán de vigía Lolo Zancalarga", tgt="Capitán de vigía Lolo Zancalarga", tag="Opcional"}, [65]={npc="Hansel Manospesadas", tgt="Hansel Manospesadas"}, [66]={npc="Hansel Manospesadas", tgt="Hansel Manospesadas", tag="Opcional"}, [67]={npc="Hansel Manospesadas", tgt="Hansel Manospesadas"}, [68]={npc="Capataz Scrange", tgt="Capataz Scrange"}, [69]={npc="Capataz Scrange", tgt="Capataz Scrange"}, [70]={npc="Maestro herrero Cremación", tgt="Maestro herrero Cremación"}, [71]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento", tag="Opcional"}, [72]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [73]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"},