    ["04-48"] = {steps={[1]={text="Desde el camino de montaña al oeste de Tanaris, baja por la rampa hasta el Cráter de Un'Goro. Abrecaminos Torwa está justo junto a la entrada, al pie de la rampa.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [2]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [3]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [4]={npc="Una balsa estropeada", npcObj=true, desc="Reúne 7 cristales de cada color (rojo, azul, verde y amarillo) y consigue «Un diario destrozado» de los raptores."}, [5]={npc="Un paquetito", npcObj=true}, [6]={npc="Un paquetito", npcObj=true}, [7]={hint="Encuentra la última presa muerta de Lar'korwi y roba un trozo de trillanodonte muerto, y después ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro."}, [8]={desc="Mata plantas por 67.7, 30.7 hasta llegar a la mitad del nivel 49."}, [9]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [10]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [11]={hint="Llévale 2 glándulas de feromonas de ravasaurio a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro."}, [12]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [13]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [14]={hint="Utiliza el contenido de la bolsa de Torwa para atraer la presencia de Lar'korwi y derrótalo. Después llévale la cabeza de Lar'korwi a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro.", tag="Opcional", desc="Esta es más difícil. Puedes dejarla para cuando vuelvas a Un'Goro."}, [15]={npc="Karna Tripirrem", tgt="Karna Tripirrem"}, [16]={npc="Linken", tgt="Linken"}, [17]={npc="Linken", tgt="Linken"}, [18]={nodeA="{a:541}"}, [19]={npc="Williden Marshal", tgt="Williden Marshal"}, [20]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [21]={npc="Chispik Nilminer", tgt="Chispik Nilminer"}, [22]={npc="J.D. Collie", tgt="J.D. Collie"}, [23]={npc="J.D. Collie", tgt="J.D. Collie"}, [24]={npc="J.D. Collie", tgt="J.D. Collie"}, [25]={npc="J.D. Collie", tgt="J.D. Collie"}, [26]={npc="J.D. Collie", tgt="J.D. Collie"}, [27]={npc="Cuidado con Pterrordax", npcObj=true}, [28]={npc="Muigin", tgt="Muigin"}, [29]={npc="Shizzle", tgt="Shizzle"}, [30]={hint="Descubre la localización de la Torre de Cristal del Norte en el Cráter de Un'Goro."}, [31]={hint="Llévale 2 pelambres de gorila de Un'Goro, 2 pelambres de vapuleador de Un'Goro y 2 pelambres de tronador de Un'Goro a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro."}, [33]={hint="Lleva un cajón de comestibles y el equipo de investigación a Williden Marshal en el Cráter de Un'Goro."}, [34]={hint="Descubre la localización de la Torre de Cristal del Este en el Cráter de Un'Goro."}, [35]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [36]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [37]={text="Sigue el camino hasta este punto."}, [38]={text="Sigue el camino hasta este punto."}, [39]={hint="Utiliza el vial raspador para recoger una Muestra de pared de la colmena de uno de los criaderos Gorishi del Cráter de Un'Goro. Busca las cámaras con los huevos de larva colgantes."}, [40]={hint="Descubre la localización de la Torre de Cristal del Oeste."}, [41]={text="Termina las misiones de matar y recolectar que tengas."}, [42]={hint="Recoge 8 escamas membranosas de diemetradón y 8 escamas membranosas de Pterrordáctilo para Shizzle, en el Refugio de Marshal."}, [43]={hint="Recoge 15 pétalos de sangre y ve a ver a Muigin."}, [44]={hint="Mata a 10 Pterrordáctilos y a 15 Pterrordáctilos dementes. Cuando lo hayas hecho habla con Spraggle Habitus en el Refugio de Marshal."}, [45]={npc="Shizzle", tgt="Shizzle"}, [46]={npc="Muigin", tgt="Muigin"}, [47]={npc="Muigin", tgt="Muigin"}, [48]={npc="Spraggle Habitus", tgt="Spraggle Habitus"}, [49]={npc="Chispik Nilminer", tgt="Chispik Nilminer"}, [50]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [51]={npc="Williden Marshal", tgt="Williden Marshal"}, [52]={npc="Un diario destrozado", npcObj=true, tag="Opcional", desc="Haz clic derecho para aceptarla solo si consigues Un diario destrozado de los enemigos."}, [53]={npc="Williden Marshal", tgt="Williden Marshal", tag="Opcional"}, [54]={npc="J.D. Collie", tgt="J.D. Collie"}, [55]={npc="J.D. Collie", tgt="J.D. Collie"}, [56]={npc="J.D. Collie", tgt="J.D. Collie"}, [57]={npc="J.D. Collie", tgt="J.D. Collie"}, [58]={npc="J.D. Collie", tgt="J.D. Collie"}, [60]={desc="Si tu piedra de hogar está en reutilización, vuela de Refugio de Marshal a Auberdine (con escala en Gadgetzan y Theramore) y sáltate los dos pasos siguientes."}, [62]={desc="Este barco hace escala en Costasur. Baja en Auberdine."}, [64]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [65]={npc="Daryn Brisela", tgt="Daryn Brisela"}, [66]={npc="Daryn Brisela", tgt="Daryn Brisela"}, [67]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus."}, [68]={npc="Gracina Poderespíritu", tgt="Gracina Poderespíritu"}, [69]={npc="Gracina Poderespíritu", tgt="Gracina Poderespíritu"}, [70]={npc="Astarii Buscaestelar", tgt="Astarii Buscaestelar", tag="Opcional"}, [71]={npc="Maginor Dumas", tgt="Maginor Dumas", tag="Opcional"}, [72]={npc="Sanath Lim-yo", tgt="Sanath Lim-yo", tag="Opcional"}, [73]={}, [74]={npc="Archimago Xylem", tgt="Archimago Xylem"}, [75]={hint="Llévale 10 puñados de polvo relumbrante al archimago Xylem."}, [76]={npc="Archimago Xylem", tgt="Archimago Xylem"}, [77]={npc="Archimago Xylem", tgt="Archimago Xylem"}, [78]={hint="Reúne 6 corales encantados y llévaselos al archimago Xylem."}, [79]={npc="Archimago Xylem", tgt="Archimago Xylem"}, [80]={npc="Archimago Xylem", tgt="Archimago Xylem", desc="Morphaz está en el Templo de Atal'Hakkar."}, [81]={hint="Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem.", desc="Morphaz está en el Templo de Atal'Hakkar."}, [82]={npc="Archimago Xylem", tgt="Archimago Xylem"}, [83]={npc="Hermano Joshua", tgt="Hermano Joshua", desc="Acéptala en Ventormenta y entrégala a Ogtinc en Azshara."}, [84]={npc="Ogtinc", tgt="Ogtinc", desc="Acéptala en Ventormenta y entrégala a Ogtinc en Azshara."}, [85]={npc="Ogtinc", tgt="Ogtinc"}, [86]={hint="Consigue 4 glándulas de trotadores sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}, [87]={npc="Ogtinc", tgt="Ogtinc"}, [88]={npc="Ogtinc", tgt="Ogtinc"}, [89]={hint="Consigue un icor de los no-muertos para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}, [90]={npc="Ogtinc", tgt="Ogtinc"}, [91]={npc="Ogtinc", tgt="Ogtinc", desc="Morphaz está en el Templo de Atal'Hakkar."}, [92]={hint="Mata a Morphaz en El Templo Sumergido de Atal'Hakkar y lleva su sangre a Greta Pezuñamusgo en Frondavil. Encontrarás la entrada al Templo Sumergido en el Pantano de las Penas.", desc="Morphaz está en el Templo de Atal'Hakkar."}, [93]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo", desc="Morphaz está en el Templo de Atal'Hakkar."}, [94]={npc="Dorion", tgt="Dorion", desc="Acéptala en Darnassus (o Forjaz, Ventormenta) y entrégala a Ogtinc en Azshara."}, [95]={npc="Ogtinc", tgt="Ogtinc", desc="Acéptala en Darnassus (o Forjaz, Ventormenta) y entrégala a Ogtinc en Azshara."}, [96]={npc="Ogtinc", tgt="Ogtinc"}, [97]={hint="Llévale un par de cuernos de corcel perfectos a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}, [98]={npc="Ogtinc", tgt="Ogtinc"}, [99]={npc="Ogtinc", tgt="Ogtinc"}, [100]={hint="Llévale 6 escamas de descarnador marino a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}, [101]={npc="Ogtinc", tgt="Ogtinc"}, [102]={npc="Ogtinc", tgt="Ogtinc", desc="El draco verde está en el Templo de Atal'Hakkar."}, [103]={hint="Llévale el colmillo de Morphaz a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", desc="El draco verde está en el Templo de Atal'Hakkar."}, [104]={npc="Ogtinc", tgt="Ogtinc", desc="El draco verde está en el Templo de Atal'Hakkar."}, [105]={text="Cruza el portal de Darnassus de vuelta a Aldea Rut'theran."}, [107]={text="Vincula tu piedra de hogar en la posada de Astranaar (37.00, 49.20)."}}},
    ["04-49"] = {steps={[1]={text="Desde Astranaar, sigue el camino al norte hasta Frondavil.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [2]={npc="Arathandris Cielargente", tgt="Arathandris Cielargente"}, [3]={npc="Grazle", tgt="Grazle"}, [4]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [5]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [6]={npc="Taronn Plumarroja", tgt="Taronn Plumarroja", tag="Opcional"}, [7]={hint="Grazle quiere que demuestres tu valía matando a 6 guerreros Muertobosque, 6 abrecaminos Muertobosque y 6 jardineros Muertobosque. Cuando lo hayas hecho, vuelve con él al sur de Frondavil, cerca del Santuario Esmeralda."}, [8]={npc="Grazle", tgt="Grazle"}, [9]={npc="Grazle", tgt="Grazle"}, [10]={hint="Mata a 11 jurapenas Fuego de Jade, 9 acechasombras Fuego de Jade, 9 pícaros Fuego de Jade y a Xavathras. Vuelve con Eridan Vientoazul a Frondavil cuando hayas completado la misión."}, [11]={hint="Entra en Jaedenar y mata a 4 canes Jaedenar, 4 soldados Jaedenar, 6 adeptos Jaedenar y 6 fieles Jaedenar antes de volver con Greta Pezuñamusgo a Frondavil."}, [12]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [13]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [14]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [15]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [16]={hint="Lleva la cantimplora vacía a la poza de la luna que hay en el centro de Jaedenar y llénala antes de volver con Greta Pezuñamusgo a Frondavil."}, [17]={desc="Mata enemigos alrededor de 35, 59 en Jaedenar."}, [18]={hint="Busca y destruye a 2 bestias entrópicas y 2 horrores entrópicos a la vez que exploras la Cañada Gran Cicatriz. Cuando hayas comprobado si los cráteres del lugar aún contienen putraqua corrupta, vuelve con Taronn Plumarroja a Frondavil.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [19]={hint="Eridan Vientoazul de Frondavil quiere que mates a 8 clamainfernos Fuego de Jade, 8 traidores Fuego de Jade, 8 timadores Fuego de Jade y a Xavaric. Vuelve con Eridan cuando lo hayas hecho."}, [20]={npc="Flauta de Xavaric", npcObj=true, desc="Haz clic derecho en Flauta de Xavaric en tu bolsa para empezar la misión."}, [21]={hint="Lleva la Flauta de Xavaric y 5 muestras de lazo maldito de Fuego de Jade a Eridan Vientoazul al Frondavil meridional."}, [22]={hint="Lleva 15 unidades de sangre ámbar a Arathandris Cielargente a Frondavil."}, [23]={node="Claro Ramaespolón"}, [24]={npc="Nafien", tgt="Nafien"}, [25]={npc="Nafien", tgt="Nafien", tag="Verificar en el juego"}, [26]={hint="Nafien quiere que mates a 6 vigilantes del cubil Muertobosque, 6 vengadores Muertobosque y 6 chamanes Muertobosque. Luego, vuelve a buscarlo al norte de Frondavil, cerca de la entrada del Bastión de los Fauces de Madera.", tag="Verificar en el juego"}, [27]={npc="Nafien", tgt="Nafien", tag="Verificar en el juego"}, [28]={text="Sigue el camino hasta este punto.", desc="Entra aquí en la cueva del Bastión de los Fauces de Madera y atraviésala para llegar a Cuna del Invierno."}, [29]={npc="Salfa", tgt="Salfa", tag="Verificar en el juego"}, [30]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [31]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [32]={npc="Meggi Rocaliz", tgt="Meggi Rocaliz"}, [33]={npc="Jessica Rutagrana", tgt="Jessica Rutagrana"}, [34]={nodeA="{a:2255}"}, [35]={npc="Niby el Todopoderoso", tgt="Niby el Todopoderoso"}, [36]={npc="Diblis", tgt="Diblis"}, [37]={npc="Diblis", tgt="Diblis"}, [38]={hint="Lleva un retal de tela de inferi a Diblis a Frondavil."}, [39]={npc="Diblis", tgt="Diblis"}, [40]={npc="Diblis", tgt="Diblis"}, [41]={hint="Lleva 10 maderas putrefactas y 4 esencias de veneno a Diblis a Frondavil."}, [42]={npc="Diblis", tgt="Diblis"}, [43]={npc="Diblis", tgt="Diblis"}, [44]={hint="Reúne un total de 6 plumas vudú en el Templo Sumergido."}, [45]={npc="Diblis", tgt="Diblis"}, [46]={npc="Diblis", tgt="Diblis"}, [47]={hint="Diblis de Frondavil te ha pedido que le lleves 3 esencias viles impecables que provengan de 3 lugares distintos. Los sátiros Legashi de Azshara tienen la esencia vil impecable de su región. Los Legionarios Jaedenar de Jaedenar tienen la esencia vil impecable de su región. Los guardias viles de Las Tierras Devastadas tienen la esencia vil impecable de su región. Reúne las esencias viles impecables y vuelve con Diblis a Frondavil."}, [48]={npc="Diblis", tgt="Diblis"}, [49]={npc="Diblis", tgt="Diblis", desc="Kroshius está al norte de Frondavil. Necesitas grupo."}, [50]={hint="Busca los restos de Kroshius en la Cañada Gran Cicatriz de Frondavil. Cuando localices sus restos, utiliza el fuego inferi cerca de ellos y espera el regreso de Kroshius. Cuando el inferno se haya despertado, acaba con él y extrae de su cuerpo el núcleo infernal de Kroshius.", desc="Kroshius está al norte de Frondavil. Necesitas grupo."}, [51]={npc="Niby el Todopoderoso", tgt="Niby el Todopoderoso", desc="Kroshius está al norte de Frondavil. Necesitas grupo."}}},
    ["04-50"] = {steps={[2]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [3]={npc="Troyas Brisaluna", tgt="Troyas Brisaluna"}, [4]={npc="Troyas Brisaluna", tgt="Troyas Brisaluna"}, [5]={npc="Gregan Vomitabrebaje", tgt="Gregan Vomitabrebaje"}, [6]={npc="Muerdepiedras", tgt="Muerdepiedras"}, [7]={hint="Busca a Gregan Vomitabrebaje en el norte de Feralas. Con él, aprende cómo puedes obtener el Elixir de Videre. Cuando lo sepas, vuelve con Donova Cubilnevado en Cuna del Invierno."}, [8]={hint="Energiza el bastón de Troyas y encuentra el Monolito de Equinex.", desc="Más adelante puedes saltar hacia arriba para atajar."}, [9]={npc="Shay Correhoja", tgt="Shay Correhoja"}, [10]={npc="Monolito de Equinex", npcObj=true, desc="Usa el bastón de tu bolsa."}, [11]={npc="Monolito de Equinex", npcObj=true}, [12]={hint="Lleva 10 pellejos gruesos de yeti Cicatriz Feral a Pratt McGrubben al Bastión Plumaluna."}, [13]={npc="Pellejo de yeti prístino", npcObj=true, tag="Opcional", desc="Si te cae un Pellejo de yeti prístino al matar yetis, haz clic derecho en él."}, [14]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [15]={npc="Pratt McGrubben", tgt="Pratt McGrubben", tag="Opcional"}, [16]={npc="Troyas Brisaluna", tgt="Troyas Brisaluna"}}},
    ["04-51"] = {steps={[1]={desc="Si tu piedra de hogar está en reutilización, vuela de Bastión Plumaluna a Astranaar (con escala en Auberdine) y luego camina al norte hasta Frondavil."}, [2]={npc="Arathandris Cielargente", tgt="Arathandris Cielargente"}, [3]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [4]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [5]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [6]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [7]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [8]={npc="Taronn Plumarroja", tgt="Taronn Plumarroja"}, [9]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado", desc="Vuelve a Astranaar, vuela al Claro Ramaespolón y sigue al norte por el Bastión de los Fauces de Madera hasta Cuna del Invierno."}, [10]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [11]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [12]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [13]={desc="Mata fúrbolgs alrededor de 32, 36 en el campamento Nevada."}, [14]={npc="Gregor Pedragris", tgt="Gregor Pedragris"}, [15]={npc="Gregor Pedragris", tgt="Gregor Pedragris"}, [16]={desc="Harás escala en Punta Talrendis."}, [17]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [18]={npc="Islen Vident'aqua", tgt="Islen Vident'aqua"}, [19]={npc="Islen Vident'aqua", tgt="Islen Vident'aqua"}, [21]={npc="Alquimista Morterozugg", tgt="Alquimista Morterozugg"}, [22]={text="Tras beber el Elixir de Videre, sigue muerto y busca al PNJ de la misión en forma de espíritu."}, [23]={npc="Gaeriyan", tgt="Gaeriyan"}, [24]={npc="Gaeriyan", tgt="Gaeriyan"}, [25]={text="Vuelve a tu cadáver y resucita."}, [26]={npc="Una lápida llamativa", npcObj=true}, [27]={npc="Una lápida llamativa", npcObj=true}, [28]={npc="Tran'rek", tgt="Tran'rek"}, [29]={npc="Alquimista Morterozugg", tgt="Alquimista Morterozugg"}}},
    ["04-52"] = {name="Cráter de Un'Goro", steps={[2]={npc="Linken", tgt="Linken"}, [3]={npc="Linken", tgt="Linken"}, [4]={npc="J.D. Collie", tgt="J.D. Collie"}, [5]={npc="J.D. Collie", tgt="J.D. Collie"}, [6]={npc="Spraggle Habitus", tgt="Spraggle Habitus"}, [7]={npc="Karna Tripirrem", tgt="Karna Tripirrem"}, [8]={hint="Reúne 12 muestras de alquitrán superpegajoso para Tran'rek de Gadgetzan."}, [9]={npc="Krakle", tgt="Krakle"}, [10]={hint="Lleva 9 muestras de ceniza de los elementales de fuego del Cráter de Un'Goro a Liv Rizzlefix a Trinquete."}, [11]={hint="Krakle, en el Cráter de Un'Goro, quiere que encuentres la zona más caliente de la Cresta del Penacho en Llamas."}, [12]={hint="Llévale una glándula secretora de olor de Gorishi y 5 muestras de la tierra de Un'Goro al alquimista Morterozugg de Gadgetzan.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [13]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [14]={npc="Krakle", tgt="Krakle"}, [15]={npc="Krakle", tgt="Krakle"}, [16]={npc="Ringo", tgt="Ringo", desc="Misión de escolta: en grupo, espera a que todos vayan igual antes de aceptarla y desactiva la aceptación automática."}, [17]={npc="Ringo", tgt="Ringo"}, [18]={npc="Spraggle Habitus", tgt="Spraggle Habitus"}, [19]={npc="Memo 01", tgt="Memo 01"}, [20]={npc="Memo 01", tgt="Memo 01"}, [21]={npc="Memo 01", tgt="Memo 01"}, [22]={hint="Llévale la piel de U'cha a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro."}, [23]={npc="Memo 01", tgt="Memo 01"}, [24]={npc="Karna Tripirrem", tgt="Karna Tripirrem"}, [25]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [26]={}, [27]={npc="Tran'rek", tgt="Tran'rek"}, [28]={npc="Alquimista Morterozugg", tgt="Alquimista Morterozugg", tag="Opcional"}, [29]={desc="Harás escala en Theramore."}, [30]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [33]={}, [35]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [36]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus."}, [37]={hint="Viaja a Darnassus y utiliza el vial de Eridan para recoger agua bendita del Templo de la Luna. Vuelve a Eridan con el vial lleno."}, [38]={text="Cruza el portal de Darnassus de vuelta a Aldea Rut'theran."}, [40]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [41]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [42]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [43]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [44]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [45]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [46]={hint="Recoge 11 zarpas plateadas y 1 corazón de Troncoferro para Eridan Vientoazul de Frondavil.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [47]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul", tag="Opcional"}, [48]={desc="Si está en reutilización, camina de vuelta a Astranaar y vuela a Auberdine."}, [49]={desc="Este barco hace escala en Costasur. Baja en Puerto de Menethil."}, [51]={npc="Karnik el Historiador", tgt="Karnik el Historiador", tag="Opcional"}, [52]={npc="Karnik el Historiador", tgt="Karnik el Historiador", tag="Opcional"}, [53]={npc="Alto Expedicionario Magellas", tgt="Alto Expedicionario Magellas", tag="Opcional"}, [54]={npc="Historiador Real Archesonus", tgt="Historiador Real Archesonus"}, [55]={npc="Historiador Real Archesonus", tgt="Historiador Real Archesonus"}, [56]={npc="Historiador Real Archesonus", tgt="Historiador Real Archesonus"}, [57]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [58]={hint="Reúne 8 champiñones de sangre y 8 aguijones Gorishi, y ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro."}, [59]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [60]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [61]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [62]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}, [63]={hint="Consigue una vid pútrida de las que custodia el guardián en las profundidades del Templo Sumergido y después ve a ver de nuevo a Torwa Abrecaminos."}, [64]={npc="Abrecaminos Torwa", tgt="Abrecaminos Torwa"}}},
    ["04-54"] = {steps={[1]={text="Si ya abriste Vigilia de Morgan, vuela directo desde Forjaz. Si no, vuela a Villa del Lago y sigue el camino al norte hasta Las Estepas Ardientes; Vigilia de Morgan está justo en la entrada.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [2]={node="Vigilia de Morgan"}, [3]={npc="Oralius", tgt="Oralius"}, [4]={npc="Oralius", tgt="Oralius"}, [5]={npc="Helendis Rivacuerno", tgt="Helendis Rivacuerno", tag="Opcional"}, [6]={npc="Tinkee Vaporio", tgt="Tinkee Vaporio"}, [7]={npc="Maxwort Suprandor", tgt="Maxwort Suprandor"}, [8]={hint="Ve a las Ruinas de Thaurissan, en Las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa a la historiadora real Archesonus."}, [9]={hint="Llévale la transcripción de la tablilla a Maxwort Suprandor en Las Estepas Ardientes."}, [10]={hint="Mata a 15 ogros magos Pirontraña, 7 ogros Pirontraña y 7 ogros brutos Pirontraña y vuelve junto a Oralius cuando hayas acabado."}, [11]={hint="Llévale 8 esencias de cría y el Draco Incarcinatrix 900 a Tinkee Vaporino en el Peñacho Llamarada, en Las Estepas Ardientes."}, [12]={hint="Mata 15 cachorrillos negros, 10 dragauros negros, 4 vermis negros y 1 draco negro. Vuelve junto a Helendis Rivacuerno cuando hayas acabado la tarea.", tag="Hazlo cuando te pille de paso"}, [13]={npc="Cyrus Therepentio", tgt="Cyrus Therepentio", tag="Opcional"}, [14]={npc="Cyrus Therepentio", tgt="Cyrus Therepentio", tag="Opcional"}, [15]={npc="Tinkee Vaporio", tgt="Tinkee Vaporio"}, [16]={npc="Maxwort Suprandor", tgt="Maxwort Suprandor"}, [17]={npc="Oralius", tgt="Oralius"}, [18]={npc="Oralius", tgt="Oralius", tag="Opcional"}, [19]={npc="Helendis Rivacuerno", tgt="Helendis Rivacuerno", tag="Opcional"}, [20]={npc="Helendis Rivacuerno", tgt="Helendis Rivacuerno", tag="Opcional"}, [21]={hint="Encuentra a Gor'tesh, en el algún lugar al oeste de la Roca Machacamiedo. Mata a Gor'tesh y llévale entonces la cabeza cortada de Gor'tesh a Oralius en Las Estepas Ardientes.", tag="Opcional"}, [22]={hint="Oralius quiere 50 medallones Roca Negra. Con toda probabilidad encontrarás estos medallones en los orcos de Las Estepas Ardientes."}, [23]={npc="Oralius", tgt="Oralius"}, [24]={npc="Oralius", tgt="Oralius", tag="Opcional"}, [25]={desc="Si no vas a hacer Los verdaderos maestros, vuela directo a Ventormenta y sáltate los dos pasos siguientes."}, [26]={npc="Magistrado Salomón", tgt="Magistrado Salomón", tag="Opcional"}, [27]={npc="Magistrado Salomón", tgt="Magistrado Salomón", tag="Opcional"}, [29]={npc="Alto Señor Bolvar Fordragon", tgt="Alto Señor Bolvar Fordragon", tag="Opcional"}, [30]={npc="Alto Señor Bolvar Fordragon", tgt="Alto Señor Bolvar Fordragon", tag="Opcional"}, [31]={npc="Alto Señor Bolvar Fordragon", tgt="Alto Señor Bolvar Fordragon", tag="Opcional"}, [32]={npc="Alto Señor Bolvar Fordragon", tgt="Alto Señor Bolvar Fordragon", tag="Opcional"}, [33]={npc="Alto Señor Bolvar Fordragon", tgt="Alto Señor Bolvar Fordragon", tag="Opcional"}, [34]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw", tag="Opcional"}, [35]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw", tag="Opcional"}, [36]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw", tag="Opcional"}, [37]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw", tag="Opcional"}, [38]={npc="Crier Bonombre", tgt="Crier Bonombre"}, [39]={npc="Wu Shen", tgt="Wu Shen", tag="Opcional"}, [40]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [41]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [42]={hint="Mata a 7 jabinfernos de Las Tierras Devastadas y vuelve junto al héroe caído de la Horda.", tag="Opcional"}, [43]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [44]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [45]={hint="Acaba con los Sombra Jurada en las Tierras Devastadas y regresa junto al Héroe Caído de la Horda.", tag="Opcional"}, [46]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [47]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [48]={hint="Llévale las plumas vudú de los trols del Templo Sumergido al Héroe Caído de la Horda.", tag="Opcional"}, [49]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [50]={npc="Lord Grisillo Quiebrasombras", tgt="Lord Grisillo Quiebrasombras", desc="Entrégala en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}},
    ["04-55"] = {steps={[1]={desc="Si ya abriste el Campamento del Orvallo, vuela directo y sáltate el siguiente paso. Si el Pico Nidal no está en tu mapa de vuelos, vuela a Costasur y corre al este hasta el Pico Nidal por el mismo camino que en la visita a las Tierras del Interior."}, [2]={text="Desde el Pico Nidal, toma el camino de montaña al norte hasta el extremo sureste de las Tierras de la Peste del Oeste (65.30, 86.80) y sigue la carretera al oeste hasta el Campamento del Orvallo.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [3]={node="Campamento del Orvallo"}, [4]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [5]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [6]={npc="Oficial Argenta Purocorazón", tgt="Oficial Argenta Purocorazón"}, [7]={npc="Oficial Argenta Purocorazón", tgt="Oficial Argenta Purocorazón"}, [8]={npc="Flint Sombramás", tgt="Flint Sombramás"}, [9]={npc="Flint Sombramás", tgt="Flint Sombramás", tag="Opcional"}, [10]={hint="Mata 10 despellejadores esqueléticos y 10 necrófagos esclavizantes en la Colina de las Penas."}, [11]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [12]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [13]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [14]={npc="Suma Sacerdotisa MacDonnel", tgt="Suma Sacerdotisa MacDonnel"}, [15]={npc="Suma Sacerdotisa MacDonnel", tgt="Suma Sacerdotisa MacDonnel"}, [16]={hint="Con la Antorcha de aviso, marca las torres de Andorhal. Tendrás que estar en la entrada de la torre para poder marcarla."}, [17]={hint="Ve al Campo de Piedra Mácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedra Mácula para obtener una muestra de los venenos utilizados en el interior de la caldera."}, [18]={npc="Caldera de la Plaga", npcObj=true}, [19]={npc="Caldera de la Plaga", npcObj=true}, [20]={npc="Janice Piedra Mácula", tgt="Janice Piedra Mácula"}, [21]={npc="Paquete de Janice", npcObj=true}, [22]={npc="Paquete de Janice", npcObj=true}, [23]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [24]={npc="Suma Sacerdotisa MacDonnel", tgt="Suma Sacerdotisa MacDonnel"}, [25]={npc="Suma Sacerdotisa MacDonnel", tgt="Suma Sacerdotisa MacDonnel"}, [26]={hint="Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera."}, [27]={npc="Caldera de la Plaga", npcObj=true}, [28]={npc="Caldera de la Plaga", npcObj=true}, [29]={npc="Suma Sacerdotisa MacDonnel", tgt="Suma Sacerdotisa MacDonnel"}, [30]={npc="Suma Sacerdotisa MacDonnel", tgt="Suma Sacerdotisa MacDonnel"}, [31]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [32]={hint="Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera."}, [33]={npc="Caldera de la Plaga", npcObj=true}, [34]={npc="Caldera de la Plaga", npcObj=true}, [35]={npc="Mulgris Riohondo", tgt="Mulgris Riohondo"}, [36]={hint="Destruye 8 lobos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste.|n|n"}, [37]={npc="Mulgris Riohondo", tgt="Mulgris Riohondo"}, [38]={npc="Mulgris Riohondo", tgt="Mulgris Riohondo"}, [39]={hint="Destruye 8 griseznos malsanos y regresa con Mulgris Riohondo en El Tormento, en las Tierras de la Peste del Oeste."}, [40]={npc="Mulgris Riohondo", tgt="Mulgris Riohondo"}, [41]={npc="Mulgris Riohondo", tgt="Mulgris Riohondo"}, [42]={text="Sigue el camino hasta este punto."}, [43]={text="Vincula tu piedra de hogar en la posada del Pico Nidal (13.80, 41.60)."}, [44]={npc="El tesoro de Cortello", npcObj=true}, [45]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [46]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [47]={hint="Recoge 20 piedras de la Plaga del esbirro y entrégaselas al sumo sacerdote Thel'danis en las Tierras de la Peste del Oeste."}, [48]={npc="Sumo Sacerdote Thel'danis", tgt="Sumo Sacerdote Thel'danis"}, [49]={npc="Sumo Sacerdote Thel'danis", tgt="Sumo Sacerdote Thel'danis"}, [50]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [51]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor", desc="Entrégala para conseguir la Piedra de poderío."}, [52]={hint="Obtén plumas vudú ámbar, azules y verdes de los trols del Templo Sumergido.", desc="Entrégala para conseguir la Piedra de poderío."}, [53]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor", desc="Entrégala para conseguir la Piedra de poderío."}}},
    ["04-56"] = {steps={[1]={text="Desde el Pico Nidal, toma el camino de montaña al norte hasta las Tierras de la Peste del Oeste y luego ve al este cruzando el río Thondroril hasta las Tierras de la Peste del Este. Tirión Vadín está en la cabaña junto a la entrada."}, [2]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [3]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [4]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [5]={hint="Mata 20 cachorros de can de la Peste, 5 canes de la Peste y 5 canes de la Peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Fordring."}, [6]={hint="Mata 30 murcípestes y vuelve con Tirion Fordring."}, [7]={hint="Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Fordring cuando tengas 14 trozos de carne de gusano carroñero."}, [8]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [9]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [10]={hint="Encuentra la muñeca de Pamela.", desc="En las casas en ruinas de Villa Darrow, recoge la cabeza, el lado izquierdo y el lado derecho, y combínalos con clic derecho."}, [11]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [12]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [13]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [14]={npc="Duque Nicholas Zverenhoff", tgt="Duque Nicholas Zverenhoff"}, [15]={node="Capilla de la Esperanza de la Luz"}, [16]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana"}, [17]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana", tag="Opcional"}, [18]={npc="Custodio Alen", tgt="Custodio Alen"}, [19]={hint="Libera a 15 espíritus de Villa Darrow y vuelve con Carlin Rutagrana.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [20]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [21]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [22]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [23]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [24]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [25]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [26]={hint="Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring."}, [27]={hint="Mata al infiltrador Hameya. Utiliza su llave en el Túmulo que hay detrás de La Subgranja."}, [28]={npc="Pergamino roto", npcObj=true}, [29]={hint="Explora las Tierras de la Peste del Este en busca de pistas sobre el \"Clamorinfecto\" y los agentes perdidos del IS:7. Si encuentras alguna insignia del IS:7 llévasela a Flint Sombramás en el Campamento del Orvallo.", tag="Opcional"}, [30]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [31]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [32]={npc="Custodio Alen", tgt="Custodio Alen"}, [33]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana", tag="Opcional"}}},
    ["04-53"] = {steps={[1]={desc="Harás escala en el Campamento del Orvallo o en el Pico Nidal; si Costasur no está en tu mapa de vuelos, vuela a Ventormenta como siempre y toma el barco a Auberdine en el puerto."}, [2]={desc="En el muelle de Costasur sale directamente un barco a Auberdine, más rápido que volar a Ventormenta y cambiar de barco. Si vuelas a Ventormenta, embarca en el puerto de Ventormenta."}, [4]={hint="Donova Cubilnevado de Cuna del Invierno quiere que mates 8 abrecaminos Nevada, 8 Vigilantes del cubil Nevada y 8 totémicos Nevada."}, [5]={hint="Salfa quiere que mates 8 chamanes Nevada, 8 Vigilantes del cubil Nevada y 8 ursas Nevada. Salfa está a las puertas del Bastión de los Fauces de Madera en Cuna del Invierno.", tag="Verificar en el juego"}, [6]={npc="Frasco vacío de piroagua", npcObj=true, desc="Haz clic derecho en Frasco vacío de piroagua en tu bolsa para empezar la misión."}, [7]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [8]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [9]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [10]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [11]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [12]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [13]={hint="Recoge 10 plumas Lunadón de Cuna del Invierno y regresa con Eralas Cieloámbar en Aldea Rut'theran."}, [14]={npc="Salfa", tgt="Salfa", tag="Verificar en el juego"}, [15]={npc="Caldera de Muertobosque", npcObj=true}, [16]={npc="Caldera de Muertobosque", npcObj=true}, [17]={}, [18]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [19]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [20]={npc="Daryn Brisela", tgt="Daryn Brisela"}, [22]={npc="Harlo Contorecio", tgt="Harlo Contorecio"}, [23]={npc="Wynd Cazanoche", tgt="Wynd Cazanoche"}, [24]={npc="Wynd Cazanoche", tgt="Wynd Cazanoche"}, [25]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras"}, [26]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras"}, [27]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras"}, [28]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras"}, [29]={hint="Utiliza el pico de Jaron para encontrar los cuatro fragmentos de reliquia de los altonatos. Llévaselas a Aurora Llamacielo en las Tierras de la Peste del Este."}, [30]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [31]={npc="Cajón dañado", npcObj=true}, [32]={npc="Cajón dañado", npcObj=true}, [33]={npc="Carro de Jaron", npcObj=true}, [34]={npc="Carro de Jaron", npcObj=true}, [35]={hint="Recoge de la nieve los Suministros de Jaron y encuentra al lechúcico que robó el amuleto del que te habló Jaron."}, [36]={npc="Ranshalla", tgt="Ranshalla"}, [37]={npc="Ranshalla", tgt="Ranshalla"}, [38]={hint="Protege a Ranshalla mientras intenta reactivar el Altar de Elune. Informa sobre tus descubrimientos a Eralas Cieloámbar de Aldea Rut'theran."}, [39]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras"}, [41]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [42]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [43]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus."}, [44]={npc="Archidruida Fandral Corzocelada", tgt="Archidruida Fandral Corzocelada"}}},
    ["04-57"] = {name="Tierras de la Peste del Oeste", steps={[1]={desc="Si tu piedra de hogar está en reutilización, cruza el portal de vuelta a Aldea Rut'theran, vuela a Auberdine, toma el barco a Puerto de Menethil, baja en Costasur y luego vuela al Campamento del Orvallo."}, [2]={desc="Si el Campamento del Orvallo no está en tu mapa de vuelos, toma el camino de montaña al norte desde el Pico Nidal hasta las Tierras de la Peste del Oeste y corre al oeste hasta el Campamento del Orvallo."}, [3]={npc="Suma Sacerdotisa MacDonnel", tgt="Suma Sacerdotisa MacDonnel"}, [4]={npc="Flint Sombramás", tgt="Flint Sombramás", tag="Opcional"}, [5]={npc="Suma Sacerdotisa MacDonnel", tgt="Suma Sacerdotisa MacDonnel"}, [6]={npc="Marlene Sendaroja", tgt="Marlene Sendaroja"}, [7]={npc="Marlene Sendaroja", tgt="Marlene Sendaroja"}, [8]={hint="Lleva la alianza de Joseph a Chromie."}, [9]={npc="Cromi", tgt="Cromi"}, [10]={npc="Cromi", tgt="Cromi"}, [11]={npc="Cromi", tgt="Cromi"}, [12]={hint="Lleva el libro Crónicas de Villa Darrow a Cromi a Andorhal."}, [13]={hint="Utiliza el desplazador temporal junto a uno de los silos de Andorhal y saca a la luz los parásitos temporales."}, [14]={npc="Cromi", tgt="Cromi"}, [15]={npc="Cromi", tgt="Cromi"}, [16]={npc="Cromi", tgt="Cromi"}, [17]={desc="Andorhal no tiene punto de vuelo. Primero camina de vuelta al sur hasta el Campamento del Orvallo y vuela desde allí."}, [18]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana"}, [19]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana", tag="Opcional"}, [20]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana"}, [21]={hint="Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo del Honor Perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring."}, [22]={hint="Lleva la cabeza de Zaeldarr al custodio Alen a la Capilla de la Esperanza de la Luz."}, [23]={npc="Aurora Llamacielo", tgt="Aurora Llamacielo"}, [24]={npc="Aurora Llamacielo", tgt="Aurora Llamacielo"}, [25]={hint="Utiliza la Jarra de termitas vacía en los Montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Nathaniel Dumah al Campamento del Orvallo en las Tierras de la Peste del Oeste."}, [26]={hint="Lleva el cráneo de Horgus y la espada destrozada de Marduk a Carlin Rutagrana a la Capilla de la Esperanza de la Luz.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [27]={npc="Túmulo de porquería", npcObj=true}, [28]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [29]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [30]={hint="Lleva el Tratado de Davil y el Escudo de Rutagrana a Carlin Rutagrana."}, [31]={hint="Ve a la Gangrena de Gahrron en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de la Gangrena de Gahrron para obtener una muestra de los venenos utilizados en el interior de la caldera."}, [32]={npc="Caldera de la Plaga", npcObj=true}, [33]={npc="Caldera de la Plaga", npcObj=true}, [34]={npc="Artista Renfray", tgt="Artista Renfray"}, [35]={npc="Suma Sacerdotisa MacDonnel", tgt="Suma Sacerdotisa MacDonnel"}, [36]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [37]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [38]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [39]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [40]={npc="Barril de termitas", npcObj=true}, [41]={npc="Barril de termitas", npcObj=true}, [42]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [43]={hint="Mata a 2 médicos Escarlata, 2 cazadores Escarlata, 2 magos Escarlata y 2 caballeros Escarlata antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste."}, [44]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [45]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [46]={hint="Mata al cazador Radley y al hidalgo Durgen antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste."}, [47]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [48]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [49]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [50]={desc="No hay punto de vuelo cerca: camina de vuelta al sur hasta el Campamento del Orvallo y vuela desde allí, o ve al este cruzando el río Thondroril y cabalga por las Tierras de la Peste del Este hasta la capilla."}, [51]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana", tag="Opcional"}, [52]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana"}, [54]={npc="Historiador Real Archesonus", tgt="Historiador Real Archesonus"}, [56]={npc="Agente Real Bathrilor", tgt="Agente Real Bathrilor"}, [57]={npc="Agente Real Bathrilor", tgt="Agente Real Bathrilor"}, [58]={npc="Vieja Emma", tgt="Vieja Emma"}, [59]={npc="Vieja Emma", tgt="Vieja Emma"}, [60]={tag="Opcional"}, [61]={npc="Magistrado Salomón", tgt="Magistrado Salomón", tag="Opcional"}, [62]={npc="Magistrado Salomón", tgt="Magistrado Salomón", tag="Opcional"}, [64]={npc="Mariscal Maxwell", tgt="Mariscal Maxwell", tag="Opcional"}, [65]={npc="Mariscal Maxwell", tgt="Mariscal Maxwell", tag="Opcional"}, [66]={hint="Habla con John Andrajoso para averiguar el destino del alguacil Windsor y vuelve junto al alguacil Maxwell cuando hayas completado la tarea."}, [67]={npc="Oralius", tgt="Oralius", tag="Opcional"}, [68]={hint="Coge la cabeza cortada de Gor'tesh y colócala en lo alto de la Roca Machacamiedo. Busca un montículo de tierra blanda para clavar la pica.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [69]={npc="Mariscal Maxwell", tgt="Mariscal Maxwell", tag="Opcional"}, [70]={npc="Oralius", tgt="Oralius", tag="Opcional"}, [71]={npc="Jalinda Espiga", tgt="Jalinda Espiga"}, [72]={text="¿Aún no eres nivel 60? Haz una