    ["05-d13"] = {name="Stratholme", entrance="Tierras de la Peste del Este 26.52, 10.36", steps={[1]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [2]={hint="Mata 20 cachorros de can de la Peste, 5 canes de la Peste y 5 canes de la Peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Fordring.", tag="Requisito de mazmorra"}, [3]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [4]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [5]={hint="Mata 30 murcípestes y vuelve con Tirion Fordring.", tag="Requisito de mazmorra"}, [6]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [7]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [8]={hint="Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Fordring cuando tengas 14 trozos de carne de gusano carroñero.", tag="Requisito de mazmorra"}, [9]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [10]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [11]={hint="Escucha lo que Tirion Fordring tiene que contarte.", tag="Requisito de mazmorra"}, [12]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [13]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [14]={hint="Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring.", tag="Requisito de mazmorra"}, [15]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [16]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [17]={hint="Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo del Honor Perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring.", tag="Requisito de mazmorra"}, [18]={npc="Tirión Vadín", tg