    [4421] = {n="La corrupción de los Fuego de Jade", d="Mata a 11 jurapenas Fuego de Jade, 9 acechasombras Fuego de Jade, 9 pícaros Fuego de Jade y a Xavathras. Vuelve con Eridan Vientoazul a Frondavil cuando hayas completado la misión.", tgo={{"Jurapenas Fuego de Jade"}, {"Acechasombras Fuego de Jade"}, {"Pícaro Fuego de Jade"}, {"Xavathras"}}},
    [4441] = {n="Los Ancestros corrompidos", d="Viaja a Darnassus y utiliza el vial de Eridan para recoger agua bendita del Templo de la Luna. Vuelve a Eridan con el vial lleno.", objs={"Templo de la Fuente de la Luna"}},
    [4442] = {n="¡Purificada!", d="Vuelve a hablar con Eridan dentro de un momento."},
    [4449] = {n="Atrapado", d="Mata a 8 geólogos Hierro Negro y lleva 15 piezas de seda a la persona encerrada en los baños de La Garganta de Fuego.", tgo={{"Geólogo Hierro Negro"}, {}}, objs={"Granito de Alterac", "Cofre ajado", "Cofre sólido"}},
    [4450] = {n="El libro de contabilidad de Tanaris", d="Coge el libro de contabilidad de Buenacero y busca los objetos de la lista antes de ir a verlo a Tanaris.", tgo={{}, {"Araña Cristalderma"}, {}, {"Jarquia"}}, objs={"Libro de contabilidad de Buenacero", "Cajón dañado"}},
    [4486] = {n="Libro de la nobleza", d="Habla con Duthorian Rall en Ventormenta."},
    [4487] = {n="Invoca un malignoecus", d="Habla con Strahad Farsan en Trinquete."},
    [4490] = {n="Invoca un malignoecus", d="Habla con Strahad Farsan en Trinquete para aprender a invocar a un malignoecus."},
    [4491] = {n="Un poco de ayuda de mis amigos", d="Lleva a Ringo con Spraggle Habitus en el Refugio de Marshal.\nSi Ringo se desmaya utiliza la cantimplora de Spraggle para reanimarlo."},
    [4492] = {n="¡Perdido!", d="Encuentra a Ringo en la Cresta del Penacho en Llamas."},
    [4493] = {n="La marcha de los silítidos", d="Ve a Gadgetzan y habla con el alquimista Morterozugg."},
    [4495] = {n="Un buen amigo", d="Encuentra a Iverron cerca de la cueva que hay al norte."},
    [4496] = {n="Que jungla tan chunga", d="Llévale una glándula secretora de olor de Gorishi y 5 muestras de la tierra de Un'Goro al alquimista Morterozugg de Gadgetzan.", tgo={{"Avispa Gorishi", "Trabajador Gorishi", "Atracador Gorishi", "Aguijonero Gorishi", "Tunelador Gorishi", "Guardia de la colmena Gorishi", "Reina de la colmena Gorishi"}, {}}, objs={"Montón de porquería de Un'Goro"}},
    [4501] = {n="Cuidado con los pterrordáctilos", d="Mata a 10 Pterrordáctilos y a 15 Pterrordáctilos dementes. Cuando lo hayas hecho habla con Spraggle Habitus en el Refugio de Marshal.", tgo={{"Pterrordáctilo"}, {"Pterrordáctilo demenciado"}}},
    [4502] = {n="Actividad volcánica", d="Lleva 9 muestras de ceniza de los elementales de fuego del Cráter de Un'Goro a Liv Rizzlefix a Trinquete.", tgo={{"Elemental agostador", "Llamarada viviente", "Correfuego", "Invasor de fuego", "Barón Charr"}}},
    [4503] = {n="El aparato volador de Shizzle", d="Recoge 8 escamas membranosas de diemetradón y 8 escamas membranosas de Pterrordáctilo para Shizzle, en el Refugio de Marshal.", tgo={{"Diemetradón joven", "Diemetradón", "Diemetradón viejo"}, {"Pterrordáctilo volantón", "Pterrordáctilo", "Pterrordáctilo demenciado"}}},
    [4504] = {n="Superpegajoso", d="Reúne 12 muestras de alquitrán superpegajoso para Tran'rek de Gadgetzan.", tgo={{"Bestia Tar", "Rondador Tar", "Señor Tar", "Trepador Tar"}}},
    [4581] = {n="Kayneth Ventoleve", d="Llévale la nota de Shindrell a Kayneth Ventoleve en Canción del Bosque."},
    [4681] = {n="Varado", d="Recoge restos de la tortuga marina esquelética de las aguas del oeste de Auberdine y vuelve a Auberdine a hablar con Gwennyth Bly'Leggonde.", objs={"Tortuga de mar esquelética"}},
    [4722] = {n="Tortuga marina varada", d="Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine."},
    [4723] = {n="Criatura marina varada", d="Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine."},
